#!/usr/bin/env node
// Demo wearable: posts a batch of vital-sign readings for one crew member to
// Demify's device API (POST /api/readings) every few seconds, as a real
// sensor hub would. Dependency-free; needs Node 20+ (built-in fetch).
//
//   npm run sensor:demo -- --url http://localhost:3000 --crew cdr
//   node scripts/sensor-demo.mjs --crew ms1 --interval 2 --count 10
//
// The values are generated by this script (a slow random walk around normal
// resting values). They are demo data, not measurements. They are stored with
// source "sensor", so the live monitor shows them instead of the simulator
// for as long as they keep arriving (fresh = newer than 2 minutes).
// When the server has an admin token, export the same DEMIFY_ADMIN_TOKEN
// before running this script; it is sent in the x-demify-admin header.
// Stop with Ctrl+C.

const HELP = `Usage: node scripts/sensor-demo.mjs [options]

Options
  --url <base>        Demify base URL            (default http://localhost:3000)
  --crew <id>         Crew id: cdr, plt, ms1, ms2 (default cdr)
  --interval <s>      Seconds between batches    (default 5, minimum 0.5)
  --count <n>         Number of batches to send  (default: until Ctrl+C)
  -h, --help          Show this help

Environment
  DEMIFY_ADMIN_TOKEN  Sent as the x-demify-admin header when set (needed
                      when the server has an admin token).`;

function parseArgs(argv) {
  const opts = { url: "http://localhost:3000", crew: "cdr", interval: 5, count: Infinity };
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === "-h" || arg === "--help") {
      console.log(HELP);
      process.exit(0);
    }
    const m = /^--(url|crew|interval|count)(?:=(.*))?$/.exec(arg);
    if (!m) fail(`Unknown option "${arg}"`);
    const value = m[2] ?? argv[++i];
    if (value === undefined || value === "") fail(`Missing value for --${m[1]}`);
    if (m[1] === "url" || m[1] === "crew") opts[m[1]] = value;
    else {
      const n = Number(value);
      if (!Number.isFinite(n) || n <= 0) fail(`--${m[1]} must be a positive number`);
      opts[m[1]] = m[1] === "count" ? Math.floor(n) : Math.max(0.5, n);
    }
  }
  try {
    opts.endpoint = new URL("/api/readings", opts.url).toString();
  } catch {
    fail(`--url "${opts.url}" is not a valid URL`);
  }
  return opts;
}

function fail(message) {
  console.error(`sensor-demo: ${message}\n\n${HELP}`);
  process.exit(2);
}

/**
 * Vital signs the Demify monitor accepts from a sensor, with the exact unit
 * the API requires (src/lib/health/knowledge.ts). `mid` is a typical resting
 * value, `sd` the size of one random step, [lo, hi] keeps the walk inside a
 * normal resting range.
 */
const VITALS = [
  { indicator: "heartRate", unit: "bpm", mid: 64, sd: 1.5, lo: 55, hi: 78, decimals: 0 },
  { indicator: "systolicBP", unit: "mmHg", mid: 117, sd: 1.5, lo: 108, hi: 128, decimals: 0 },
  { indicator: "diastolicBP", unit: "mmHg", mid: 75, sd: 1, lo: 68, hi: 82, decimals: 0 },
  { indicator: "spo2", unit: "%", mid: 98, sd: 0.4, lo: 96, hi: 99, decimals: 0 },
  { indicator: "respRate", unit: "/min", mid: 14, sd: 0.5, lo: 12, hi: 18, decimals: 0 },
  { indicator: "bodyTemp", unit: "°C", mid: 36.7, sd: 0.05, lo: 36.3, hi: 37.1, decimals: 1 },
];

const state = new Map(VITALS.map((v) => [v.indicator, v.mid]));

function nextBatch(crewId) {
  const takenAt = new Date().toISOString();
  return VITALS.map((v) => {
    // Random step plus a gentle pull back towards the typical value.
    const prev = state.get(v.indicator);
    const step = (Math.random() * 2 - 1) * v.sd + (v.mid - prev) * 0.1;
    const value = Math.min(v.hi, Math.max(v.lo, prev + step));
    state.set(v.indicator, value);
    return {
      crewId,
      indicator: v.indicator,
      value: Number(value.toFixed(v.decimals)),
      unit: v.unit,
      takenAt,
      source: "sensor",
    };
  });
}

function summary(batch) {
  const get = (id) => batch.find((r) => r.indicator === id)?.value;
  return (
    `HR ${get("heartRate")} bpm, BP ${get("systolicBP")}/${get("diastolicBP")} mmHg, ` +
    `SpO2 ${get("spo2")} %, RR ${get("respRate")}/min, T ${get("bodyTemp")} °C`
  );
}

let stopping = false;
let wake = null;
function sleep(ms) {
  return new Promise((resolve) => {
    const t = setTimeout(resolve, ms);
    wake = () => {
      clearTimeout(t);
      resolve();
    };
  });
}
process.on("SIGINT", () => {
  if (stopping) process.exit(130);
  stopping = true;
  console.log("\nsensor-demo: stopping (Ctrl+C again to force)");
  wake?.();
});

/** Admin token for servers with write protection; empty or unset sends no header. */
const ADMIN_TOKEN = process.env.DEMIFY_ADMIN_TOKEN?.trim() ?? "";

async function post(endpoint, batch) {
  const res = await fetch(endpoint, {
    method: "POST",
    headers: { "content-type": "application/json", ...(ADMIN_TOKEN ? { "x-demify-admin": ADMIN_TOKEN } : {}) },
    body: JSON.stringify(batch),
    signal: AbortSignal.timeout(10_000),
  });
  let body = null;
  try {
    body = await res.json();
  } catch {
    /* not JSON (e.g. an HTML error page from a proxy) */
  }
  return { res, body };
}

const opts = parseArgs(process.argv.slice(2));
console.log(
  `sensor-demo: posting demo vitals for crew "${opts.crew}" to ${opts.endpoint} ` +
    `every ${opts.interval} s${Number.isFinite(opts.count) ? `, ${opts.count} batch(es)` : ""}` +
    `${ADMIN_TOKEN ? ", with the admin token header" : ""}. Ctrl+C stops.`,
);

let sent = 0;
let failures = 0;
let backoffS = opts.interval;
while (!stopping && sent < opts.count) {
  const batch = nextBatch(opts.crew);
  const time = new Date().toLocaleTimeString();
  let waitS = opts.interval;
  let rateLimited = false;
  try {
    const { res, body } = await post(opts.endpoint, batch);
    if (res.status === 201) {
      sent++;
      failures = 0;
      backoffS = opts.interval;
      console.log(`${time}  201 created ${body?.created?.length ?? batch.length}  ${summary(batch)}`);
    } else if (res.status === 429) {
      const retryAfter = Number(res.headers.get("retry-after"));
      waitS = Number.isFinite(retryAfter) && retryAfter > 0 ? retryAfter : opts.interval * 2;
      rateLimited = true;
      console.warn(`${time}  429 rate limited, waiting ${waitS} s`);
    } else {
      const message = body?.error ?? res.statusText;
      console.error(`${time}  ${res.status} ${message}`);
      if (res.status === 401) {
        console.error(
          ADMIN_TOKEN
            ? "          the server rejected DEMIFY_ADMIN_TOKEN: export the token the server was started with"
            : "          the server has an admin token: export DEMIFY_ADMIN_TOKEN and run again",
        );
      }
      // A 4xx other than 429 will not fix itself: wrong crew id, unit or URL.
      if (res.status >= 400 && res.status < 500) process.exit(1);
      failures++;
    }
  } catch (err) {
    failures++;
    const reason = err?.cause?.code ?? err?.name ?? "error";
    console.error(`${time}  network error (${reason}): ${err?.cause?.message ?? err?.message ?? err}`);
  }
  if (failures > 0 && !rateLimited) {
    // Exponential backoff on network/server errors, capped at 60 s. The first
    // retry waits one interval, then 2x, 4x ... A 429 always honours Retry-After.
    waitS = backoffS;
    backoffS = Math.min(60, backoffS * 2);
    console.warn(`          retrying in ${waitS} s (attempt ${failures})`);
  }
  if (!stopping && sent < opts.count) await sleep(waitS * 1000);
}
console.log(`sensor-demo: ${sent} batch(es) accepted.`);
